package com.sintax;

public class ExampleVariable {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		// variabili con tipo di dato primitivo

		// INT
		int number = 10;

		// BOOLEAN
		boolean started = true;

		// CHAR
		char symbol = 'a';

		// LONG
		long pIva = 123456789;

		// DOUBLE
		double decimal = 30.50;

		// FLOAT
		float numbers = 10.32f;

		// VARIABILE CLASSE STRING
		String name = "Francesco";
		
		//System.out.println(pIva);
		//System.out.println(name);

		// per indentare il codice fare in sequenza:
		// Ctrl + A
		// Ctrl + Shift + F
		
		int giorno = 7;
		int mese = 1;
		int anno = 1927;
		
		int età = 187;
		int anni = età;
		
		String employeeFirstName = "Francesco";
		String employeeLastName = "Vespari";
		String employeeRole = "Developer";
 
		System.out.println("Impiegato: " + employeeFirstName + " " + employeeLastName + " - Ruolo: " + employeeRole);
		System.out.println("Data di nascita: " + giorno + " / " + mese + " / " + anno);
		System.out.println("Età: " + anni);
		
	}

}
